function a(r,n="INR",t=!1){const e=Number(r)||0;if(t&&Math.abs(e)>=1e6){const i=e/1e6;return`${n==="INR"?"₹":"$"}${i.toFixed(2)}M`}if(t&&Math.abs(e)>=1e3){const i=e/1e3;return`${n==="INR"?"₹":"$"}${i.toFixed(1)}K`}return new Intl.NumberFormat("en-IN",{style:"currency",currency:n,minimumFractionDigits:2,maximumFractionDigits:2}).format(e)}function s(r,n=1){const t=Number(r)||0;return`${(t>1?t:t*100).toFixed(n)}%`}function u(r,n=""){const t=Number(r)||0;return`${t>=0?"+":""}${n}${t.toFixed(2)}`}export{u as a,s as b,a as f};
